fn parse(s: &str) -> PgUuid {
    uuid_in(s.as_bytes(), None).unwrap()
}

fn out(u: &PgUuid) -> String {
    let mut buf = [0u8; UUID_OUT_LEN];
    let len = uuid_out_into(u, &mut buf);
    String::from_utf8(buf[..len].to_vec()).unwrap()
}

#[test]
fn differential_valid_vs_live_pg() {
    for v in VALID {
        let u = parse(v.input);
        assert_eq!(out(&u), v.out, "out mismatch for {:?}", v.input);
        assert_eq!(uuid_hash(&u), v.hash, "hash mismatch for {:?}", v.input);
        assert_eq!(uuid_hash_extended(&u, 0), v.hx0, "hx0 mismatch for {:?}", v.input);
        assert_eq!(uuid_hash_extended(&u, 11), v.hx11, "hx11 mismatch for {:?}", v.input);
        assert_eq!(uuid_extract_version(&u), v.ver, "version mismatch for {:?}", v.input);
        let ts = uuid_extract_timestamp(&u).map(|t| t + PG_EPOCH_UNIX_USECS);
        assert_eq!(ts, v.ts, "timestamp mismatch for {:?}", v.input);
    }
}

#[test]
fn differential_invalid_vs_live_pg() {
    for (input, msg) in INVALID {
        let err = uuid_in(input.as_bytes(), None).unwrap_err();
        assert_eq!(err.sqlstate(), ERRCODE_INVALID_TEXT_REPRESENTATION, "{input:?}");
        assert_eq!(err.message(), *msg, "{input:?}");

        let mut soft = SoftErrorContext::new(true);
        assert!(uuid_in(input.as_bytes(), Some(&mut soft)).is_ok());
        assert!(soft.error_occurred(), "{input:?}");
    }
}

#[test]
fn sort_order_matches_live_pg() {
    let mut parsed: Vec<PgUuid> = VALID[..120].iter().map(|v| parse(v.input)).collect();
    parsed.sort_by(|a, b| uuid_internal_cmp(a, b).cmp(&0));
    let got: Vec<String> = parsed.iter().map(out).collect();
    assert_eq!(got.join(","), SORTED);
}

#[test]
fn comparisons() {
    let lo = parse("11111111-1111-1111-1111-111111111111");
    let hi = parse("11111111-1111-1111-1111-111111111112");
    assert!(uuid_lt(&lo, &hi) && uuid_le(&lo, &hi) && uuid_ne(&lo, &hi));
    assert!(uuid_gt(&hi, &lo) && uuid_ge(&hi, &lo));
    assert!(uuid_eq(&lo, &lo) && uuid_le(&lo, &lo) && uuid_ge(&lo, &lo));
    assert_eq!(uuid_internal_cmp(&lo, &hi), -1);
    assert_eq!(uuid_internal_cmp(&hi, &lo), 1);
    assert_eq!(uuid_internal_cmp(&lo, &lo), 0);
}

#[test]
fn binary_wire_round_trip() {
    use ::mcx::MemoryContext;
    let ctx = MemoryContext::new("uuid-wire");
    let mcx = ctx.mcx();

    for v in VALID.iter().step_by(17) {
        let u = parse(v.input);
        let b = uuid_send(mcx, &u).unwrap();
        assert_eq!(b.data(), &u[..]);
        let mut si = StringInfo::with_capacity_in(mcx, b.data().len() + 1).unwrap();
        si.append_bytes(b.data()).unwrap();
        assert_eq!(uuid_recv(&mut si).unwrap(), u);
        assert_eq!(si.cursor, si.len());
    }
}

fn gmt_session() {
    static ONCE: std::sync::Once = std::sync::Once::new();
    ONCE.call_once(|| {
        // SAFETY: single-threaded test init, before any getenv (adt_timestamp
        // tests' precedent).
        unsafe { std::env::set_var("PGRUST_TZDIR", "/usr/share/zoneinfo") };
        pgtz::init_seams();
        adt_timestamp::init_seams();
        guc_tables::init_seams();
        elog::init_seams();
        fd::init_seams();
        xact_seams::get_current_sub_transaction_id::set(|| 1);
    });
    adt_datetime::tz::pg_timezone_initialize();
    adt_datetime::tz::set_session_timezone(adt_datetime::tz::pg_tzset(b"GMT"));
}

fn wall_clock_us() -> i64 {
    let d = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap();
    d.as_micros() as i64 - PG_EPOCH_UNIX_USECS
}

#[test]
fn gen_random_uuid_is_valid_v4() {
    let mut seen = std::collections::HashSet::new();
    for _ in 0..64 {
        let u = gen_random_uuid().unwrap();
        assert_eq!(u[6] >> 4, 4);
        assert_eq!(u[8] & 0xc0, 0x80);
        assert_eq!(uuid_extract_version(&u), Some(4));
        assert_eq!(uuid_extract_timestamp(&u), None);
        assert!(seen.insert(u));
    }
}

#[test]
fn uuidv7_monotonic_and_valid() {
    let mut prev = uuidv7().unwrap();
    assert_eq!(uuid_extract_version(&prev), Some(7));
    for _ in 0..4096 {
        let u = uuidv7().unwrap();
        assert_eq!(u[6] >> 4, 7);
        assert_eq!(u[8] & 0xc0, 0x80);
        assert!(uuid_internal_cmp(&u, &prev) > 0);
        prev = u;
    }
}

#[test]
fn uuidv7_timestamp_tracks_wall_clock() {
    let before = wall_clock_us();
    let u = uuidv7().unwrap();
    let after = wall_clock_us();
    let ts = uuid_extract_timestamp(&u).unwrap();
    // ms-truncated extraction; the burst guard can also push it slightly ahead.
    assert!(ts >= before - US_PER_MS && ts <= after + US_PER_MS, "{ts} not in [{before}, {after}]");
}

#[test]
fn uuidv7_interval_shifts_timestamp() {
    gmt_session();
    let hour = adt_datetime::Interval { time: 3_600_000_000, day: 0, month: 0 };
    let now = wall_clock_us();
    let u = uuidv7_interval(&hour).unwrap();
    let ts = uuid_extract_timestamp(&u).unwrap();
    assert!((ts - now - 3_600_000_000).abs() < 60_000_000, "{ts} vs {now}");
    assert_eq!(uuid_extract_version(&u), Some(7));

    let back = adt_datetime::Interval { time: -3_600_000_000, day: 0, month: 0 };
    let u = uuidv7_interval(&back).unwrap();
    let ts = uuid_extract_timestamp(&u).unwrap();
    let now = wall_clock_us();
    assert!((now - ts - 3_600_000_000).abs() < 60_000_000, "{ts} vs {now}");
}

// fnconf batch-1, OID 6430 crash family: an infinite interval shift makes
// timestamptz_pl_interval return DT_NOEND/DT_NOBEGIN and C's epoch re-base
// wraps under -fwrapv, still producing a version-7 UUID
// (C 18.3: SELECT uuidv7('infinity'::interval) → a UUID, no error).
// Red at base: debug add-with-overflow panic in uuidv7_interval.
#[test]
fn uuidv7_infinite_interval_returns_uuid() {
    let u = uuidv7_interval(&adt_datetime::Interval::NOEND).unwrap();
    assert_eq!(uuid_extract_version(&u), Some(7));
    let u = uuidv7_interval(&adt_datetime::Interval::NOBEGIN).unwrap();
    assert_eq!(uuid_extract_version(&u), Some(7));
}
